\begin{tikzpicture}

% Axis
\draw[line width=0.3mm] (-3.5,0) -- (5.5,0);
\foreach \i in {-3,...,5} % numbers on line
{
	\draw (\i,0.1) -- + (0,-0.2) node[below] {$\i$};
}

% Red line
\draw[red, line width=0.5mm,<                   -](-3.5,0) -- (4,0);
